// Backend entry point: the single handler that every request goes through (route lookup, input parsing, handler call, error mapping).
// The order of the first three imports matters.
// dotenv must load first so DATABASE_URL and JWT_SECRET exist before any other file reads them.
// reflect-metadata is required by the TypeORM decorators.
// HandlerRegistry is generated by CEF (cef-gen-handlers) and lets CEF find our handlers by name.
import "dotenv/config";
import "reflect-metadata";
import "./generated/HandlerRegistry";

import {
	APIGatewayProxyStructuredResultV2,
	buildCommonEvent,
	getRouteConfig,
	resolveHandlerRef,
	Response,
	startDevServer
} from "commoneventframework";
import { CommonEvent, LambdaEvent } from "commoneventframework/dist/types/commonEvent";
import { initDatabase } from "./db/dataSource";
import { toErrorResponse } from "./errors/toErrorResponse";
import { HandlerFn, InputParserFn } from "./handlers/types";

// Every request goes through here: find the route, parse the input, run the handler.
// Any error thrown on the way is caught at the bottom and turned into a JSON error response.
export const handler = async (event: LambdaEvent): Promise<APIGatewayProxyStructuredResultV2> => {
	try {
		await initDatabase();
		const commonEvent: CommonEvent = buildCommonEvent(event);
		const routeConfig = getRouteConfig(commonEvent);

		if (!routeConfig?.handler) {
			return new Response(404, { error: "Route not found" });
		}

		const handlerFn = resolveHandlerRef(routeConfig.handler) as HandlerFn | undefined;
		const parserFn = routeConfig.inputParser
			? (resolveHandlerRef(routeConfig.inputParser) as InputParserFn | undefined)
			: undefined;

		if (!handlerFn) {
			return new Response(500, { error: `Handler "${routeConfig.handler}" not found` });
		}

		// The parser validates the raw request and gives the handler clean, typed input.
		// It runs before the handler, so invalid input is refused with a 400 before any other check.
		const input = parserFn ? parserFn(commonEvent) : {};
		const result = await handlerFn(input, commonEvent);

		// A handler can return a ready Response (to choose the status, like 201) or a plain object (sent as 200).
		if (result && "statusCode" in result) {
			return result as APIGatewayProxyStructuredResultV2;
		}
		return new Response(200, result as object);
	} catch (error) {
		return toErrorResponse(error);
	}
};

// With "--local" (npm run dev) we start CEF's local server on port 8888, instead of waiting for AWS Lambda calls.
if (process.argv.includes("--local")) {
	startDevServer(handler);
}
